104: func greenhouseElapsedLabel(start, now time.Time) string {
105: 	if start.IsZero() || now.Before(start) {
106: 		return "0s"
107: 	}
108: 	elapsed := now.Sub(start).Round(time.Second)
109: 	if elapsed < time.Minute {
110: 		return elapsed.String()
111: 	}
112: 	return fmt.Sprintf("%dm", int(elapsed.Round(time.Minute)/time.Minute))
113: }
