282: 	output, err := command.Output()
283: 	if err != nil {
284: 		return greenhouseWatchSnapshot{}
285: 	}
286: 	var snapshot greenhouseWatchSnapshot
287: 	if json.Unmarshal(output, &snapshot) != nil {
288: 		return greenhouseWatchSnapshot{}
289: 	}
290: 	if snapshot.RunID == "" {
291: 		snapshot.RunID = snapshot.Run.ID
292: 	}
293: 	return snapshot
294: }
