296: func (s *Service) reportGreenhouseTaskMetadata(ctx context.Context, db *store.DB, project store.Project, task store.Task, watch store.GreenhouseTaskWatch, snapshot greenhouseWatchSnapshot) {
297: 	if task.HerdrWorkspaceID == "" || s.Herdr == nil {
298: 		return
299: 	}
300: 	now := time.Now()
301: 	label := greenhouseElapsedSummary(watch, now)
302: 	if snapshot.Run.Pipeline != nil && snapshot.Run.Pipeline.RepairLimit > 0 {
303: 		label = watch.Stage + " · fix " + fmt.Sprintf("%d/%d", snapshot.Run.Pipeline.RepairUsed, snapshot.Run.Pipeline.RepairLimit)
304: 	}
305: 	if watch.Status == "needs-decision" {
306: 		label = "waiting for decision"
307: 	} else if watch.Status == "ci-ready" || watch.Status == "locally-ready" {
308: 		label = "PR green"
309: 	} else if watch.Status == "failed" || watch.Status == "recovery-required" {
310: 		label = "failed: " + strings.TrimSpace(watch.Stage)
311: 	}
312: 	notices, err := db.UndeliveredNotices(ctx, project.ID)
313: 	if err != nil {
314: 		return
315: 	}
316: 	_, _ = s.herdrCall(ctx, "workspace.report_metadata", map[string]any{
317: 		"workspace_id": task.HerdrWorkspaceID, "source": "posse",
318: 		"tokens": map[string]string{"posse": fmt.Sprint(len(notices)), "greenhouse": label},
319: 	})
320: }
321: 
322: func greenhousePaneExists(ctx context.Context, s *Service, task store.Task, paneID string) bool {
323: 	if paneID == "" || s.Herdr == nil {
324: 		return false
325: 	}
326: 	snapshot, err := s.snapshot(ctx)
327: 	if err != nil {
328: 		return false
329: 	}
330: 	for _, pane := range snapshot.Panes {
331: 		if pane.PaneID == paneID && pane.WorkspaceID == task.HerdrWorkspaceID {
332: 			return true
333: 		}
334: 	}
335: 	return false
336: }
337: 
338: func (s *Service) openGreenhousePane(ctx context.Context, task store.Task) (string, error) {
339: 	snapshot, err := s.snapshot(ctx)
340: 	if err != nil {
341: 		return "", err
342: 	}
343: 	for _, pane := range snapshot.Panes {
344: 		if pane.WorkspaceID == task.HerdrWorkspaceID && filepath.Clean(pane.CWD) == filepath.Clean(task.WorktreePath) && pane.PaneID != task.PaneID && strings.Contains(pane.Label, "greenhouse") {
345: 			return pane.PaneID, nil
346: 		}
347: 	}
348: 	raw, err := s.herdrCall(ctx, "pane.split", map[string]any{"target_pane_id": task.PaneID, "direction": "right", "cwd": task.WorktreePath, "focus": false})
349: 	if err != nil {
350: 		return "", err
351: 	}
352: 	var result struct {
353: 		Pane struct {
354: 			PaneID string `json:"pane_id"`
355: 		} `json:"pane"`
356: 	}
357: 	if json.Unmarshal(raw, &result) != nil || result.Pane.PaneID == "" {
358: 		return "", fmt.Errorf("herdr did not return the Greenhouse pane")
359: 	}
360: 	paneID := result.Pane.PaneID
361: 	if _, err := s.herdrCall(ctx, "pane.rename", map[string]any{"pane_id": paneID, "label": "greenhouse:" + task.PaneLabel}); err != nil {
362: 		return "", err
363: 	}
364: 	if _, err := s.herdrCall(ctx, "pane.send_input", map[string]any{"pane_id": paneID, "text": "greenhouse", "keys": []string{"enter"}}); err != nil {
365: 		return "", err
366: 	}
367: 	return paneID, nil
368: }
