62: func greenhouseElapsedSummary(watch store.GreenhouseTaskWatch, now time.Time) string {
63: 	runStart := watch.RunStartedAt
64: 	if runStart == 0 {
65: 		runStart = watch.RunObservedAt
66: 	}
67: 	stageStart := watch.StageStartedAt
68: 	if stageStart == 0 {
69: 		stageStart = watch.StageObservedAt
70: 	}
71: 	stageEnd := watch.StageFinishedAt
72: 	if stageEnd > 0 {
73: 		now = time.UnixMilli(stageEnd)
74: 	}
75: 	return watch.Stage + " " + greenhouseElapsedLabel(time.UnixMilli(stageStart), now) + " · run " + greenhouseElapsedLabel(time.UnixMilli(runStart), now)
76: }
