212: 	cfg, err := config.Load(home, project.Name)
213: 	if err != nil {
214: 		return configError(err)
215: 	}
216: 	s.startWorkerGoCacheTrim(ctx, db, project, home)
217: 	defer func() {
218: 		// Detached goroutines stop once ctx is done; wait so none writes under
219: 		// the posse home after the caller has torn it down.
220: 		if ctx.Err() != nil {
221: 			s.waitForWatchMaintenance(4 * time.Second)
222: 		}
223: 	}()
224: 	if ctx.Err() == nil {
225: 		if err := s.observeGreenhouseTasks(ctx, db, project); err != nil {
