229: 			return err
230: 		}
231: 	}
232: 	if project.IsWorkspace() {
233: 		var failures []error
234: 		if err := s.autoTeardownMergedTasks(ctx, db, project, cfg); err != nil {
235: 			failures = append(failures, fmt.Errorf("merged Task Teardown: %w", err))
236: 		}
237: 		if err := retryRemoteBranchCleanups(ctx, db, project, cfg); err != nil {
238: 			failures = append(failures, fmt.Errorf("remote branch cleanup: %w", err))
239: 		}
240: 		if err := s.startWorkspacePRPolls(ctx, db, project, cfg); err != nil {
241: 			failures = append(failures, fmt.Errorf("PR polling: %w", err))
242: 		}
243: 		if err := s.startWorkspaceCheckoutSync(ctx, db, project, cfg); err != nil {
244: 			failures = append(failures, fmt.Errorf("checkout sync: %w", err))
245: 		}
